        "ਗਾਂਧੀ ਜੀ ਨੇ ਪਿਤਾ ਜੀ ਨੂੰ ਚਿੱਠੀ ਲਿਖ ਕੇ ਆਪਣੀ ਗ਼ਲਤੀ ਮੰਨੀ",
        "ਸਿੱਖਿਆ: ਸੱਚ ਬੋਲੋ, ਚੋਰੀ ਨਾ ਕਰੋ"
