        { q: "ਪਿਤਾ ਜੀ ਨੇ ਚਿੱਠੀ ਪੜ੍ਹ ਕੇ ਕੀ ਕੀਤਾ?", a: "ਉਹ ਰੋ ਪਏ, ਕੁਝ ਦੇਰ ਅੱਖਾਂ ਬੰਦ ਕਰ ਕੇ ਲੇਟੇ ਰਹੇ ਤੇ ਫਿਰ ਚਿੱਠੀ ਪਾੜ ਦਿੱਤੀ। ਇਸ ਤਰ੍ਹਾਂ ਉਨ੍ਹਾਂ ਨੇ ਪੁੱਤਰ ਨੂੰ ਮਾਫ਼ ਕਰ ਦਿੱਤਾ।" }
