          "ਉਹ ਕਹਿੰਦੇ ਹਨ ਕਿ ਪਾਣੀ ਕੁਦਰਤ ਦੀ ਦਾਤ ਹੈ ਅਤੇ ਸਰੀਰ ਦੀ ਸਫ਼ਾਈ ਲਈ ਜ਼ਰੂਰੀ ਹੈ।",
