          "ਡਾਕਖ਼ਾਨਾ ਚਿੱਠੀਆਂ ਨੂੰ ਇੱਕ ਥਾਂ ਤੋਂ ਦੂਜੀ ਥਾਂ ਪਹੁੰਚਾਉਂਦਾ ਹੈ।",
