          "ਵੱਖ-ਵੱਖ ਥਾਂਵਾਂ ਦੀਆਂ ਚਿੱਠੀਆਂ ਵੱਖਰੇ ਥੈਲਿਆਂ ਵਿੱਚ ਪਾ ਕੇ ਬੱਸਾਂ, ਰੇਲਗੱਡੀਆਂ ਅਤੇ ਹਵਾਈ ਜਹਾਜ਼ਾਂ ਰਾਹੀਂ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
