          "ਉਸ ਨੇ ਇੱਕ ਸੋਹਣਾ ਤੋਤਾ ਪਾਲਿਆ ਹੋਇਆ ਸੀ ਜਿਸ ਦਾ ਨਾਂ ਮੀਆਂ ਮਿੱਠੂ ਸੀ।",
          "ਦੂਰ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਨੇ ਸਭ ਤੋਂ ਪੁੱਛਿਆ ਕਿ ਉਹ ਕੀ ਲਿਆਵੇ। ਤੋਤੇ ਨੇ ਕਿਹਾ ਕਿ ਮੈਨੂੰ ਕੁਝ ਨਹੀਂ ਚਾਹੀਦਾ, ਬੱਸ ਤੋਤਿਆਂ ਨੂੰ ਮੇਰਾ ਸਲਾਮ ਕਹਿ ਦੇਣਾ।"
