        { q: "ਛਿੰਦੀ ਕਿਸ ਦੇ ਗੀਟੇ ਲਿਆਈ?", options: ["ਲਾਖ ਦੇ","ਇੱਟ ਦੇ","ਲੱਕੜ ਦੇ","ਸੰਗਮਰਮਰ ਦੇ"], answer: 3, explain: "ਛਿੰਦੀ ਸੰਗਮਰਮਰ ਦੇ ਪੰਜ ਗੀਟੇ ਘੜ ਕੇ ਲਿਆਈ।" },
        { q: "ਗੀਟਾ ਬੋਚਿਆ ਨਾ ਜਾਵੇ ਤਾਂ ਕੀ ਹੁੰਦਾ ਹੈ?", options: ["ਖਿਡਾਰੀ ਆਊਟ ਹੋ ਜਾਂਦਾ ਹੈ","ਖਿਡਾਰੀ ਜਿੱਤ ਜਾਂਦਾ ਹੈ","ਖੇਡ ਰੁਕ ਜਾਂਦੀ ਹੈ","ਗੀਟੇ ਬਦਲ ਜਾਂਦੇ ਹਨ"], answer: 0, explain: "ਗੀਟਾ ਨਾ ਬੋਚਿਆ ਜਾਵੇ ਤਾਂ ਆਊਟ ਹੋ ਜਾਂਦੇ ਹਨ।" },
        { q: "\"ਪੁੱਗਣਾ\" ਕਿਸ ਲਈ ਕੀਤਾ ਜਾਂਦਾ ਹੈ?", options: ["ਖਾਣਾ ਖਾਣ ਲਈ","ਜੋੜੀਆਂ ਜਾਂ ਵਾਰੀ ਚੁਣਨ ਲਈ","ਸੌਣ ਲਈ","ਪੜ੍ਹਨ ਲਈ"], answer: 1, explain: "ਖੇਡਣ ਤੋਂ ਪਹਿਲਾਂ ਪੁੱਗ ਕੇ ਜੋਟੀਆਂ ਬਣਦੀਆਂ ਹਨ।" },
        { q: "ਕੁੜੀਆਂ ਨੇ ਦਾਦੀ-ਮਾਂ ਨੂੰ ਅੰਤ ਵਿੱਚ ਕੀ ਕਿਹਾ?", options: ["ਅਸੀਂ ਕੰਮ ਨਹੀਂ ਕੀਤਾ","ਸਾਨੂੰ ਪੜ੍ਹਨਾ ਚੰਗਾ ਨਹੀਂ ਲੱਗਦਾ","ਅਸੀਂ ਸਕੂਲ ਦਾ ਕੰਮ ਮੁਕਾ ਕੇ ਆਈਆਂ ਹਾਂ","ਅਸੀਂ ਸਾਰੀ ਰਾਤ ਖੇਡਾਂਗੀਆਂ"], answer: 2, explain: "ਉਨ੍ਹਾਂ ਨੇ ਕਿਹਾ ਕਿ ਸਕੂਲ ਦਾ ਕੰਮ ਕਰ ਕੇ ਆਈਆਂ ਸਾਂ।" }
