          "ਦਰਸ਼ਨੀ ਡਿਓੜ੍ਹੀ ਤੋਂ ਲੰਮੇ ਪੁਲ ਰਾਹੀਂ ਅੰਦਰ ਜਾ ਕੇ ਮੱਥਾ ਟੇਕਿਆ। ਇੱਥੇ ਸਾਰਾ ਦਿਨ ਕੀਰਤਨ ਹੁੰਦਾ ਰਹਿੰਦਾ ਹੈ।",
          "ਉਨ੍ਹਾਂ ਨੇ ਪ੍ਰਸ਼ਾਦ ਲੈ ਕੇ ਸ੍ਰੀ ਅਕਾਲ ਤਖ਼ਤ ਸਾਹਿਬ ਦੇ ਦਰਸ਼ਨ ਕੀਤੇ, ਸਿੱਖ ਅਜਾਇਬ-ਘਰ ਵੇਖਿਆ ਅਤੇ ਲੰਗਰ-ਹਾਲ ਵਿੱਚ ਪੰਗਤ ਵਿੱਚ ਬੈਠ ਕੇ ਲੰਗਰ ਛਕਿਆ।"
